+const fs = require('fs');
+const path = require('path');
+
+const { chromium } = require('playwright');
+
+function mustGetArg(name) {
+  const idx = process.argv.indexOf(name);
+  if (idx === -1 || !process.argv[idx + 1]) {
+    throw new Error(`Missing required arg ${name}`);
+  }
+  return process.argv[idx + 1];
+}
+
+function escapeForTemplateLiteral(s) {
+  // We embed the DSL inside a JS template literal.
+  return s.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${');
+}
+
+async function main() {
+  const dslPath = mustGetArg('--dsl');
+  const outPath = mustGetArg('--out');
+  const width = Number(mustGetArg('--width'));
+  const height = Number(mustGetArg('--height'));
+
+  const dsl = fs.readFileSync(dslPath, 'utf8');
+  const safeDsl = escapeForTemplateLiteral(dsl);
+
+  const html = `<!doctype html>
+  <html lang="en">
+    <head>
+      <meta charset="utf-8" />
+      <meta name="viewport" content="width=device-width, initial-scale=1" />
+      <title>Global Education Poster - Render</title>
+      <style>
+        html, body { margin: 0; padding: 0; background: #0b1220; }
+        #container { width: ${width}px; height: ${height}px; }
+      </style>
+    </head>
+    <body>
+      <div id="container"></div>
+      <script src="/app/vendor/infographic.min.js"></script>
+      <script>
+        (async () => {
+          const infographic = new AntVInfographic.Infographic({
+            container: '#container',
+            width: ${width},
+            height: ${height},
+          });
+          const syntax = ` + "`" + `${safeDsl}` + "`" + `;
+          infographic.render(syntax);
+          try {
+            await (document.fonts?.ready ?? Promise.resolve());
+          } catch (e) {}
+          infographic.render(syntax);
+          window.__RENDER_DONE__ = true;
+        })();
+      </script>
+    </body>
+  </html>`;
+
+  const browser = await chromium.launch();
+  const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 2 });
+  await page.setContent(html, { waitUntil: 'load' });
+  await page.waitForFunction(() => window.__RENDER_DONE__ === true, null, { timeout: 60_000 });
+  await page.waitForTimeout(500);
+  await page.screenshot({
+    path: outPath,
+    fullPage: false,
+    clip: { x: 0, y: 0, width, height },
+    omitBackground: false,
+  });
+  await browser.close();
+
+  const stat = fs.statSync(outPath);
+  if (!stat.size) {
+    throw new Error(`Screenshot produced empty file: ${outPath}`);
+  }
+  process.stdout.write(`OK ${path.resolve(outPath)} (${stat.size} bytes)\n`);
+}
+
